Span<nint> values = stackalloc nint[] { 1, 2, 3, 4, 5 };

Console.WriteLine($"Length: {values.Length}");
Console.WriteLine($"Element size: {sizeof(nint)} bytes");

nint sum = 0;
foreach (var v in values)
    sum += v;

Console.WriteLine($"Sum: {sum}");

// Also test with a fixed-size stackalloc
Span<nint> fixed_span = stackalloc nint[8];
for (int i = 0; i < fixed_span.Length; i++)
    fixed_span[i] = (nint)(i * 10);

